/**
 * The graph surfaces, on `src/api/schema.d.ts` — generated by `make types` from
 * the real pydantic models and held to the tree by `make lint-generated`.
 *
 * One name here is deliberately NOT the wire type and must not become it.
 * `GraphFilters` below is client state: it is camelCase, it holds
 * `hideIsolated`, and it is what the filter rail binds to. The generated schema
 * also has a `GraphFilters` — snake_case, four fields, the query the server
 * accepts — and they are different objects that happen to share a word. Aliasing
 * this onto that would typecheck for exactly as long as the two agreed.
 *
 * `venona__api__schemas__graph__GraphNode` is the generated name because
 * `api/schemas/entity.py` declares a `GraphNode` too, and openapi-typescript
 * disambiguates by module path. The short names are re-exported here so no
 * component has to write that.
 */

import type { components } from '@/api/schema'

type Schemas = components['schemas']

export type GraphNode = Schemas['venona__api__schemas__graph__GraphNode']
export type GraphEdge = Schemas['venona__api__schemas__graph__GraphEdge']

/** What the projection is NOT showing. Only `active` entities are projected, so
 *  a relationship with one uncorroborated endpoint cannot appear. Reported so a
 *  sparse graph reads as a corroboration gate rather than as weak extraction. */
export type GraphCoverage = Schemas['GraphCoverage']

/**
 * `coverage` is widened to optional on purpose.
 *
 * `/graph/overview` answers `GraphOverviewResponse`, where it is required;
 * every other graph endpoint answers `GraphPayloadResponse`, which has no such
 * field. `stores/graph.ts` holds results from both in one ref, so the type it
 * holds is the looser of the two. The store reads `payload.coverage ?? null`,
 * which is correct for both.
 */
export type GraphPayload = Schemas['GraphPayloadResponse'] & {
  coverage?: GraphCoverage
  /** Optional for the same reason `coverage` is: only `/graph/overview` can
   *  withhold an entity for having no edge, and the store holds every graph
   *  endpoint's result in one ref. */
  isolated_hidden?: number
}

export type PathResult = Schemas['GraphPathResponse']

export type ProvenanceAssertion = Schemas['ProvenanceAssertion']

export type EdgeProvenance = Schemas['EdgeProvenanceResponse']

export type OntologyMeta = Schemas['OntologyResponse']

/** What a brief named, and how much of it the projection can show.
 *
 *  NOT `GraphCoverage`: that counts the whole corpus, and "97 of 468 known
 *  relationships" printed under a twelve-edge canvas describes a different
 *  population from the one on screen.
 *
 *  `missing` is what the brief named but the projection does not hold: still
 *  uncorroborated, or merged away. */
export type BriefScope = Schemas['BriefScope']

export type BriefSubgraphPayload = Schemas['BriefSubgraphResponse']

/** A search hit. `degree` and `mention_count` are what let a searcher choose:
 *  "army" matches a dozen entities, and "41 connections" identifies the one
 *  that matters. */
export type GraphSearchHit = Schemas['EntitySearchHit']

/**
 * CLIENT STATE, not a wire type. See the header: the generated schema's
 * `GraphFilters` is the server's query model and is a different shape.
 */
export interface GraphFilters {
  types: string[]
  predicates: string[]
  minSourceCount: number
  /** Hide entities with no surviving relationship. On by default: a third of
   *  the corpus is edgeless and they dominate the bounding box, which is what
   *  forced the whole-graph view to fit at an illegible zoom. Never silent --
   *  the readout states the count and offers the undo. */
  hideIsolated: boolean
  /** Draw names only one source has given us, hollow rather than withheld.
   *  Off by default: the corroborated graph is the one worth landing on, and
   *  turning it on roughly doubles both result sets (ADR 0247). */
  includeUnconfirmed: boolean
}

/** `GET /graph/search`. `entities` is optional on the model. */
export type GraphSearchResponse = Schemas['GraphSearchResponse']
